// Reports Catalogue (M63): every report in the MYOB Reports Prompt Library (M00–M63) under MYOB's Reporting tabs, with what this
// agent offers for each. Generated by mk-catalogue.js from catalogue-index.json and the kit's families — edit those, then npm run gen.
MK.app({
  title: 'Reports Catalogue', primary: 'company_files', files: 'company_files',
  inputs: { companyFile: 'company_file', persona: 'persona', display: 'display' },
  defaults: { company_file: '', persona: 'Client',
    display: '{"cents":1,"k":0,"zeros":1,"neg":"paren","red":0,"hdr":1,"ftr":1,"style":"myob","dens":"100","p":"custom","a":"custom","c":"none","v":"all","x":""}' },
  uses: { company_files: [] },
  tools: { company_files: 'list_company_files (the client selector)' },
  catalogue: /*CATALOGUE*/null,
  render: function (c) {
    var K = this.catalogue, h = MK.h, body = c.body, self = this;
    var TABS = [['all', 'All']].concat(K.groups.map(function (g) { return [g[0], g[1]]; })).concat([['fav', '★ Favourites']]);
    var tab = TABS.some(function (t) { return t[0] === c.display.v; }) ? c.display.v : 'all';
    var fav = String(c.display.x || '').split(',').filter(function (m) { return K.rows.some(function (r) { return r.m === m; }); });
    var STATUS = { live: ['Live template', 'live'], request: ['On request', 'req'], export: ['From your MYOB export', 'exp'], guide: ['Guide', 'exp'], none: ['Not yet', 'off'] };
    var count = function (s) { return K.rows.filter(function (r) { return r.status === s; }).length; };
    var card = function (r) {
      var st = STATUS[r.status] || STATUS.none, on = fav.indexOf(r.m) >= 0;
      return '<div class="ct-card' + (r.status === 'none' ? ' off' : '') + '" data-text="' + h((r.name + ' ' + r.desc + ' ' + r.m + ' ' + (r.ask || '')).toLowerCase()) + '">' +
        '<div class="ct-top"><span class="ct-name">' + h(r.name) + '</span><button type="button" class="ct-star' + (on ? ' on' : '') + '" data-m="' + h(r.m) + '" aria-pressed="' + on + '" title="' + (on ? 'Remove from favourites' : 'Add to favourites') + '">' + (on ? '★' : '☆') + '</button></div>' +
        '<div class="ct-desc">' + h(r.desc) + '</div>' + (r.ask ? '<div class="ct-ask">' + h(r.ask) + '</div>' : '') +
        '<div class="ct-foot"><span class="ct-badge ' + st[1] + '">' + st[0] + '</span><span class="muted">' + h(r.m) + '</span></div></div>';
    };
    var groups = K.groups.filter(function (g) { return tab === 'all' || tab === 'fav' || tab === g[0]; });
    var sections = groups.map(function (g) {
      var rows = K.rows.filter(function (r) { return r.group === g[0] && (tab !== 'fav' || fav.indexOf(r.m) >= 0); });
      return rows.length ? '<section class="ct-sec"><h2>' + h(g[2]) + '</h2><div class="ct-grid">' + rows.map(card).join('') + '</div></section>' : '';
    }).join('');
    body.innerHTML = '<style>.ct-grid{display:grid;grid-template-columns:repeat(auto-fill,minmax(250px,1fr));gap:12px}.ct-sec h2{font-size:16px;margin:20px 0 10px}' +
      '.ct-card{background:var(--card);border:1px solid var(--line);border-radius:8px;padding:12px 14px;display:flex;flex-direction:column;gap:6px}.ct-card.off{opacity:.55}' +
      '.ct-top{display:flex;justify-content:space-between;gap:8px}.ct-name{font-weight:700;color:var(--accent)}.ct-desc{font-size:13px;color:var(--muted);flex:1}.ct-ask{font-size:12px}' +
      '.ct-foot{display:flex;justify-content:space-between;align-items:center;font-size:11px}.ct-badge{font-weight:700;border-radius:10px;padding:2px 8px;background:var(--line);color:var(--muted)}' +
      '.ct-badge.live{background:var(--pass-bg);color:var(--pos)}.ct-badge.req{color:var(--accent)}.ct-star{font:inherit;font-size:18px;line-height:1;background:none;border:0;color:var(--accent);cursor:pointer;padding:0}' +
      '.ct-tabs{display:flex;flex-wrap:wrap;gap:8px;margin:10px 0}.ct-tab{font:inherit;font-size:13px;border:1px solid var(--line);background:var(--card);color:var(--ink);border-radius:16px;padding:5px 14px;cursor:pointer}' +
      '.ct-tab.on{background:var(--accent);border-color:var(--accent);color:var(--btn-ink)}</style>' +
      MK.kpis([{ label: 'Reports in the library', money: false, value: K.rows.length }, { label: 'Live templates', money: false, value: count('live') }, { label: 'On request', money: false, value: count('request') },
        { label: 'From an export or a guide', money: false, value: count('export') + count('guide') }, { label: 'Favourites', money: false, value: fav.length }], c) +
      '<input id="ct-q" type="search" class="mk-filter" style="width:100%;margin-top:12px" placeholder="Search reports" aria-label="Search reports" value="' + h(self._q || '') + '">' +
      '<div class="ct-tabs" role="tablist">' + TABS.map(function (t) { return '<button type="button" role="tab" class="ct-tab' + (t[0] === tab ? ' on' : '') + '" data-tab="' + t[0] + '" aria-selected="' + (t[0] === tab) + '">' + h(t[1]) + '</button>'; }).join('') + '</div>' +
      '<div id="ct-sections">' + (sections || '<p class="muted">' + (tab === 'fav' ? 'No favourites yet — press ☆ on a report.' : 'No reports in this tab.') + '</p>') + '</div><p id="ct-none" class="muted" hidden>No reports match the search.</p>';
    function filter() {
      var q = (self._q || '').trim().toLowerCase(), any = false;
      body.querySelectorAll('.ct-sec').forEach(function (s) { var n = 0; s.querySelectorAll('.ct-card').forEach(function (cd) { var okq = !q || cd.getAttribute('data-text').indexOf(q) >= 0; cd.hidden = !okq; if (okq) n++; }); s.hidden = !n; if (n) any = true; });
      var none = document.getElementById('ct-none'); if (none) none.hidden = any || !body.querySelector('.ct-sec');
    }
    var qi = document.getElementById('ct-q'); qi.addEventListener('input', function () { self._q = qi.value; filter(); }); filter();
    body.querySelectorAll('.ct-tab').forEach(function (b) { b.addEventListener('click', function () { c.change({}, { v: b.getAttribute('data-tab') }); }); });
    body.querySelectorAll('.ct-star').forEach(function (b) { b.addEventListener('click', function () { var m = b.getAttribute('data-m'), i = fav.indexOf(m), f = fav.slice(); if (i >= 0) f.splice(i, 1); else f.push(m); c.change({}, { x: f.join(',') }); }); });
    var ids = K.rows.map(function (r) { return r.m; }), uniq = ids.filter(function (m, i) { return ids.indexOf(m) === i && /^M\d\d$/.test(m); });
    var byGroup = {}; K.rows.forEach(function (r) { byGroup[r.group] = (byGroup[r.group] || 0) + 1; });
    var tabsOk = K.groups.every(function (g) { return g[3] == null || byGroup[g[0]] === g[3]; });
    this._x = { rows: K.rows, STATUS: STATUS, fav: fav };
    return { checks: [
      { name: 'Every report maps to a prompt ID in this library (M00–M63)', pass: uniq.length === K.total && ids.length === K.total, detail: uniq.length + ' of ' + K.total + ' prompt IDs' },
      { name: 'Reports per MYOB tab match MYOB (Business 14 · Banking 5 · Payroll 12 · Sales 8 · Purchases 7 · Inventory 6 · Jobs 6)', pass: tabsOk, detail: K.groups.map(function (g) { return g[1] + ' ' + (byGroup[g[0]] || 0); }).join(' · ') },
      { name: 'Coverage', pass: null, info: true, detail: count('live') + ' live templates · ' + count('request') + ' on request · ' + count('export') + ' from an export · ' + count('guide') + ' guide' + (count('none') ? ' · ' + count('none') + ' not yet' : '') }],
      title: 'Reports Catalogue', period: K.total + ' reports · MYOB Reports Prompt Library v1.2',
      notes: ['Live template = a tested report the agent creates from its template; ask for it by the name shown. On request = the agent writes the report from its specification each time. From your MYOB export = MYOB\'s API does not expose it: attach the MYOB export and ask for it. Prompt IDs refer to the MYOB Reports Prompt Library v1.2.',
        'Stars last while this catalogue is open and go into its downloads. To keep favourites, ask the agent to save the catalogue with them.'] };
  },
  excel: function (c) {
    var x = this._x; if (!x) return [];
    var G = {}; this.catalogue.groups.forEach(function (g) { G[g[0]] = g[1]; });
    return [{ name: 'Reports catalogue', widths: [14, 36, 8, 22, 40, 90, 10], rows: [[{ v: c.company || 'N/A — not in source', s: 'title' }], [{ v: 'Reports Catalogue', s: 'bold' }], [],
      [{ v: 'Tab', s: 'bold' }, { v: 'Report', s: 'bold' }, { v: 'Prompt ID', s: 'bold' }, { v: 'Status', s: 'bold' }, { v: 'Ask for', s: 'bold' }, { v: 'Description', s: 'bold' }, { v: 'Favourite', s: 'bold' }]]
      .concat(x.rows.map(function (r) { return [G[r.group] || r.group, r.name, r.m, (x.STATUS[r.status] || x.STATUS.none)[0], r.ask || '', r.desc, x.fav.indexOf(r.m) >= 0 ? '★' : '']; })) }];
  }
});
